def agent_action(sandbox, agent_body, step_count):
    # Get current position of the craft
    pos = sandbox.get_craft_position()
    x, y = pos

    # Get current heat and overheat limit
    h = sandbox.get_heat()
    limit = sandbox.get_overheat_limit()
    n = sandbox.get_step_count()
    remaining_steps = 10000 - n

    # Define waypoints through the gates and target
    waypoints = [
        (13.0, 1.9),  # Center of Gate 1
        (23.0, 2.4),  # Center of Gate 2
        (30.0, 3.5)   # Final target
    ]

    # Determine the current target based on x position
    if x < 12.0:
        target = waypoints[0]
    elif 12.0 <= x <= 14.0:
        target = waypoints[0]
    elif 14.0 < x < 22.0:
        target = waypoints[1]
    elif 22.0 <= x <= 24.0:
        target = waypoints[1]
    else:
        target = waypoints[2]

    target_x, target_y = target

    # Calculate direction vector to the target
    dx = target_x - x
    dy = target_y - y
    distance = (dx**2 + dy**2)**0.5

    # If very close to the target, stop thrust
    if distance < 0.5:
        sandbox.apply_thrust(0, 0)
        return

    # Calculate maximum allowable thrust per step to avoid overheat
    if remaining_steps > 0:
        # Use a higher base thrust but cap it to avoid overheat
        max_thrust = 1.0
        if (h + max_thrust * remaining_steps) > limit:
            max_thrust = (limit - h) / remaining_steps
    else:
        max_thrust = 0.0

    # Apply thrust with gate-specific adjustments
    if 12.0 <= x <= 14.0:
        # Prioritize horizontal movement through Gate 1
        f1 = max_thrust
        # Vertical adjustment to stay within gate bounds
        if y < 1.0:
            f2 = max_thrust * 0.5
        elif y > 2.8:
            f2 = -max_thrust * 0.5
        else:
            f2 = 0.0
        # Clamp vertical thrust
        if abs(f2) > max_thrust:
            f2 = max_thrust * (1 if f2 > 0 else -1)
    elif 22.0 <= x <= 24.0:
        # Prioritize horizontal movement through Gate 2
        f1 = max_thrust
        # Vertical adjustment to stay within gate bounds
        if y < 1.8:
            f2 = max_thrust * 0.5
        elif y > 3.0:
            f2 = -max_thrust * 0.5
        else:
            f2 = 0.0
        # Clamp vertical thrust
        if abs(f2) > max_thrust:
            f2 = max_thrust * (1 if f2 > 0 else -1)
    else:
        # Normal direction-based thrust when not in a gate
        if distance == 0:
            f1, f2 = 0, 0
        else:
            scale = max_thrust / distance
            f1 = dx * scale
            f2 = dy * scale

    # Apply the calculated thrust
    sandbox.apply_thrust(f1, f2)
